cce-admin:onKeyDown (event) => {
              if (
                event.target === event.currentTarget &&
                (event.key === 'Enter' || event.key === ' ')
              ) {
                event.preventDefault();
                toggle();
              }
            }

cce-admin:onSubmit handleSubmit(({ cdsid, requestReference }) => {
        reset();
        setLastUser(cdsid);
        onSave(cdsid, requestReference);
      })

cce-admin:onClick () =>
                    onSelectAll(
                      values.filter((c) =>
                        filteredValues.some((v) => v.value === c.id),
                      ),
                    )
